const filtro = $('Prepara Filtro').item.json.filtro;
const dataInizio = $('Prepara Filtro').item.json.dataInizio;
const dataFine = $('Prepara Filtro').item.json.dataFine;

const eventi = [];

// Leggi eventi Outlook
if (filtro === 'outlook' || filtro === 'entrambi') {
  const outlookData = $('Leggi Outlook').item.json;
  const outlookEventi = outlookData.value || [];
  for (const ev of outlookEventi) {
    eventi.push({
      calendario: 'Outlook',
      titolo: ev.subject || '(senza titolo)',
      inizio: ev.start?.dateTime?.slice(0, 16).replace('T', ' ') || '',
      fine: ev.end?.dateTime?.slice(0, 16).replace('T', ' ') || ''
    });
  }
}

// Leggi eventi Google
if (filtro === 'google' || filtro === 'entrambi') {
  const googleData = $('Leggi Google').item.json;
  const googleEventi = googleData.items || [];
  for (const ev of googleEventi) {
    eventi.push({
      calendario: 'Google',
      titolo: ev.summary || '(senza titolo)',
      inizio: ev.start?.dateTime?.slice(0, 16).replace('T', ' ') || ev.start?.date || '',
      fine: ev.end?.dateTime?.slice(0, 16).replace('T', ' ') || ev.end?.date || ''
    });
  }
}

// Ordina per orario di inizio
eventi.sort((a, b) => a.inizio.localeCompare(b.inizio));

if (eventi.length === 0) {
  return [{ json: { output: `Nessun evento trovato dal ${dataInizio} al ${dataFine}.` } }];
}

const lista = eventi.map(e => 
  `[${e.calendario}] ${e.titolo} — ${e.inizio}`
).join('\n');

return [{ json: { 
  output: `Eventi dal ${dataInizio} al ${dataFine}:\n${lista}`
} }];

const tipo = $input.first().json.tipo || 'relativo';
const valore = ($input.first().json.valore || 'oggi').toLowerCase();
const filtro = $input.first().json.filtro_calendario || 'entrambi';

const oggi = DateTime.now().setZone('Europe/Rome');
let dataInizio, dataFine;

if (tipo === 'relativo') {
  if (valore === 'oggi') {
    dataInizio = oggi.toFormat('yyyy-MM-dd');
    dataFine = oggi.toFormat('yyyy-MM-dd');
  } else if (valore === 'domani') {
    const domani = oggi.plus({ days: 1 });
    dataInizio = domani.toFormat('yyyy-MM-dd');
    dataFine = domani.toFormat('yyyy-MM-dd');
  } else if (valore === 'questa_settimana') {
    dataInizio = oggi.startOf('week').toFormat('yyyy-MM-dd');
    dataFine = oggi.endOf('week').toFormat('yyyy-MM-dd');
  } else if (valore === 'prossima_settimana') {
    const prossima = oggi.plus({ weeks: 1 });
    dataInizio = prossima.startOf('week').toFormat('yyyy-MM-dd');
    dataFine = prossima.endOf('week').toFormat('yyyy-MM-dd');
  } else {
    dataInizio = oggi.toFormat('yyyy-MM-dd');
    dataFine = oggi.toFormat('yyyy-MM-dd');
  }
} else {
  // tipo === 'assoluto': valore è già una data YYYY-MM-DD
  dataInizio = valore;
  dataFine = valore;
}

return [{ json: { 
  filtro,
  dataInizio,
  dataFine,
  leggi_outlook: filtro === 'outlook' || filtro === 'entrambi',
  leggi_google: filtro === 'google' || filtro === 'entrambi'
} }];
